ark s2\"></i><i class=\"ipb-spark s3\"></i><i class=\"ipb-spark s4\"></i>\r\n  <i class=\"ipb-spark s5\"></i><i class=\"ipb-spark s6\"></i>\r\n</div>\r\n  <header class=\"ipb-hud-top\">\r\n    <div class=\"ipb-glass ipb-hud-glass\">\r\n      <div class=\"ipb-hprog\"><i></i><b></b></div>\r\n      <div class=\"ipb-sec-row\">\r\n        <span class=\"ipb-sec-num\">{{remainingSec}}</span>\r\n        <span class=\"ipb-sec-badge\">SEC</span>\r\n      </div>\r\n    </div>\r\n    <div class=\"ipb-phase\">COOL DOWN</div>\r\n  </header>\r\n  <section class=\"ipb-warmup-layout\">\r\n    <div class=\"ipb-panel ipb-video-frame\" style=\"min-height:620px\">\r\n      <div data-mvn-video class=\"ipb-video\"></div>\r\n    </div>\r\n    <div class=\"ipb-next-col\">\r\n      <div class=\"ipb-glass ipb-next-glass\">\r\n        <p class=\"ipb-next-lbl\">NEXT</p>\r\n        <div class=\"ipb-panel ipb-next-box ipb-video-frame\">\r\n          <div data-mvn-next-video class=\"ipb-video\"></div>\r\n        </div>\r\n      </div>\r\n      <p class=\"ipb-hidden-tokens\">{{label}} {{next.label}} {{totalSec}} {{stepIndex}} {{stepTotal}} {{pointColor}}</p>\r\n    </div>\r\n  </section>\r\n</div>", "title": "쿨다운", "version": 1, "titleOnly": false, "hasVideoSlot": true, "hasNextVideoSlot": true}, "6592c531-cc1f-46bf-8dc9-9ccb51db2690": {"id": "6592c531-cc1f-46bf-8dc9-9ccb51db2690", "css": ".ipb-stage{\r\n  --sand:#FFE8CF;--peach:#FFD2B0;--coral:#FF6A45;--coral-deep:#E84A3C;--aqua:#7ECEC9;--teal:#4DB6AC;--cream:#FFF8F0;--gold:#E8C36A;--ink:#2A3340;--pc:{{pointColor}};\r\n  --display:\"Archivo Black\",\"Arial Black\",Impact,\"Helvetica Neue Black\",sans-serif;\r\n  position:relative;width:1920px;height:1080px;overflow:hidden;color:var(--ink);\r\n  font-family:\"Trebuchet MS\",\"Segoe UI\",Verdana,sans-serif;\r\n  background:\r\n    radial-gradient(ellipse 90% 70% at 75% 85%,rgba(126,206,201,.62) 0%,transparent 58%),\r\n    radial-gradient(ellipse 75% 55% at 18% 12%,rgba(255,210,176,.95) 0%,transparen