ding:0 20px;margin-bottom:20px;\r\n  border-radius:999px;background:linear-gradient(180deg,#FF8A60,#FF5A3A);\r\n  color:#fff;font-size:22px;font-weight:800;letter-spacing:.1em;\r\n  box-shadow:0 4px 0 #D04028\r\n}\r\n.ipb-phase{\r\n  display:inline-flex;align-items:center;justify-content:center;\r\n  padding:16px 32px;border-radius:18px;background:rgba(255,248,240,.92);\r\n  border:4px solid rgba(255,160,110,.65);color:var(--coral-deep);\r\n  font-size:36px;font-weight:900;letter-spacing:.14em;\r\n  box-shadow:0 6px 16px rgba(80,40,20,.08)\r\n}\r\n\r\n.ipb-center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:2;text-align:center}\r\n.ipb-title-prog{width:85%;max-width:1632px;margin-top:36px;height:30px}\r\n.ipb-title-prog>i{width:88%}\r\n.ipb-title-prog>b{left:88%;width:46px;height:46px;margin:-23px 0 0 -23px}\r\n\r\n.ipb-hud-top{position:absolute;left:56px;top:36px;right:56px;z-index:3;display:grid;grid-template-columns:1fr auto;gap:28px;align-items:start}\r\n.ipb-hud-glass{padding:22px 28px 18px;display:flex;flex-direction:column;gap:14px;max-width:1180px}\r\n.ipb-hud-glass .ipb-hprog{width:100%}\r\n.ipb-hud-left{display:flex;flex-direction:column;gap:14px}\r\n\r\n.ipb-warmup-layout{position:absolute;left:56px;right:56px;top:250px;bottom:56px;z-index:2;display:grid;grid-template-columns:1.55fr .9fr;gap:40px;align-items:stretch}\r\n.ipb-next-col{display:flex;flex-direction:column;align-items:center;gap:0}\r\n.ipb-next-glass{width:100%;padding:28px 28px 32px;display:flex;flex-direction:column;align-items:center;gap:18px;box-sizing:border-box}\r\n.ipb-next-lbl{font-size:56px;font-weight:900;letter-spacing:.4em;color:var(--coral);margin:0;padding-left:.4em}\r\n.ipb-next-box{width:100%;aspect-ratio:16/10;max-height:440px}\r\n\r\n.ipb-split-layout{position:absolute;left:56px;right:56px;top:250px;bottom:48px;z-index:2;display:grid;grid-template-columns:1.3fr 1.05fr;gap:36px;align-items:stretch}\r\n.ipb-muscl