4F6,#E2E8EC);border-radius:20px;overflow:hidden}\r\n.ipb-video-frame{position:relative;overflow:hidden}\r\n.ipb-video-frame .ipb-video{position:absolute;inset:12px;width:auto;height:auto;border-radius:18px}\r\n\r\n.ipb-hprog{\r\n  position:relative;height:30px;border-radius:999px;overflow:visible;\r\n  background:#fff;\r\n  border:3px solid rgba(255,200,150,.45);\r\n  box-shadow:inset 0 2px 4px rgba(0,0,0,.04),0 2px 8px rgba(0,0,0,.08)\r\n}\r\n.ipb-hprog>i{\r\n  position:absolute;left:0;top:0;bottom:0;width:62%;border-radius:999px;\r\n  background:linear-gradient(90deg,#4DB6AC 0%,#7CB342 48%,#FF8A50 100%);\r\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.45)\r\n}\r\n.ipb-hprog>b{\r\n  position:absolute;top:50%;left:62%;width:40px;height:40px;margin:-20px 0 0 -20px;\r\n  border-radius:50%;background:#fff;border:4px solid #F2F2F2;\r\n  box-shadow:0 3px 10px rgba(0,0,0,.2)\r\n}\r\n.ipb-sec-row{display:flex;align-items:flex-end;gap:16px}\r\n.ipb-sec-num{\r\n  font-family:var(--display);font-size:128px;font-weight:900;line-height:.88;font-variant-numeric:tabular-nums;\r\n  letter-spacing:.02em;\r\n  background:linear-gradient(180deg,#FF7A55,#E83A30);-webkit-background-clip:text;background-clip:text;\r\n  color:transparent;-webkit-text-fill-color:transparent\r\n}\r\n.ipb-sec-badge{\r\n  display:inline-flex;align-items:center;justify-content:center;\r\n  min-width:76px;height:46px;padding:0 20px;margin-bottom:20px;\r\n  border-radius:999px;background:linear-gradient(180deg,#FF8A60,#FF5A3A);\r\n  color:#fff;font-size:22px;font-weight:800;letter-spacing:.1em;\r\n  box-shadow:0 4px 0 #D04028\r\n}\r\n.ipb-phase{\r\n  display:inline-flex;align-items:center;justify-content:center;\r\n  padding:16px 32px;border-radius:18px;background:rgba(255,248,240,.92);\r\n  border:4px solid rgba(255,160,110,.65);color:var(--coral-deep);\r\n  font-size:36px;font-weight:900;letter-spacing:.14em;\r\n  box-shadow:0 6px 16px rgba(80,40,20,.08)\r\n}\r\n\r\n.ipb-center{position:absolute;inset:0;displ