etch:expanded\r\n}\r\n.ipb-display-lg{font-size:236px;width:85%;max-width:1632px;letter-spacing:.12em;white-space:nowrap}\r\n.ipb-display-cooldown{\r\n  /* \"COOL DOWN\" one line ≈85% of 1920 stage */\r\n  font-size:168px;letter-spacing:.06em;width:85%;max-width:1632px;white-space:nowrap\r\n}\r\n.ipb-display-md{font-size:188px;width:85%;max-width:1632px;letter-spacing:.14em;white-space:nowrap}\r\n.ipb-outline{\r\n  font-family:var(--display);font-weight:400;letter-spacing:.42em;text-transform:uppercase;\r\n  color:rgba(255,255,255,.35);-webkit-text-stroke:2.5px #6A9AA8;\r\n  paint-order:stroke fill\r\n}\r\n\r\n.ipb-glass{\r\n  background:rgba(255,252,246,.48);\r\n  border:2px solid rgba(255,255,255,.72);\r\n  border-radius:28px;\r\n  box-shadow:0 10px 28px rgba(60,80,90,.08),inset 0 1px 0 rgba(255,255,255,.75);\r\n  backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)\r\n}\r\n.ipb-panel{\r\n  background:var(--cream);border:7px solid #E0C080;border-radius:28px;\r\n  box-shadow:0 10px 28px rgba(80,60,40,.12),inset 0 0 0 4px rgba(255,255,255,.7)\r\n}\r\n.ipb-video{width:100%;height:100%;background:linear-gradient(160deg,#F0F4F6,#E2E8EC);border-radius:20px;overflow:hidden}\r\n.ipb-video-frame{position:relative;overflow:hidden}\r\n.ipb-video-frame .ipb-video{position:absolute;inset:12px;width:auto;height:auto;border-radius:18px}\r\n\r\n.ipb-hprog{\r\n  position:relative;height:30px;border-radius:999px;overflow:visible;\r\n  background:#fff;\r\n  border:3px solid rgba(255,200,150,.45);\r\n  box-shadow:inset 0 2px 4px rgba(0,0,0,.04),0 2px 8px rgba(0,0,0,.08)\r\n}\r\n.ipb-hprog>i{\r\n  position:absolute;left:0;top:0;bottom:0;width:62%;border-radius:999px;\r\n  background:linear-gradient(90deg,#4DB6AC 0%,#7CB342 48%,#FF8A50 100%);\r\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.45)\r\n}\r\n.ipb-hprog>b{\r\n  position:absolute;top:50%;left:62%;width:40px;height:40px;margin:-20px 0 0 -20px;\r\n  border-radius:50%;background:#fff;border:4px solid #F2F2F2;\r\n  box-sha