rection:column;align-items:center;gap:0}\r\n.ipb-next-glass{width:100%;padding:28px 28px 32px;display:flex;flex-direction:column;align-items:center;gap:18px;box-sizing:border-box}\r\n.ipb-next-lbl{font-size:56px;font-weight:900;letter-spacing:.4em;color:var(--coral);margin:0;padding-left:.4em}\r\n.ipb-next-box{width:100%;aspect-ratio:16/10;max-height:440px}\r\n\r\n.ipb-split-layout{position:absolute;left:56px;right:56px;top:250px;bottom:48px;z-index:2;display:grid;grid-template-columns:1.3fr 1.05fr;gap:36px;align-items:stretch}\r\n.ipb-muscles{\r\n  display:flex;align-items:center;justify-content:center;padding:16px 14px 18px;height:100%;box-sizing:border-box;overflow:hidden\r\n}\r\n.ipb-muscles-img{\r\n  display:block;width:100%;height:100%;max-width:100%;max-height:100%;object-fit:contain;object-position:center\r\n}\r\n\r\n.ipb-stage--exercise .ipb-float,.ipb-stage--exercise .ipb-palm-bl{display:none}\r\n.ipb-ex-layout{position:absolute;inset:0;z-index:2;display:grid;grid-template-columns:400px 1fr;gap:32px;padding:40px 48px 48px}\r\n.ipb-ex-side{display:flex;flex-direction:column;align-items:flex-start;gap:20px;padding-top:8px;min-height:0}\r\n.ipb-ex-timer .ipb-sec-num{font-size:196px}\r\n.ipb-ex-timer .ipb-seconds-lbl{\r\n  display:block;margin-top:2px;font-size:30px;font-weight:800;letter-spacing:.36em;color:var(--gold);\r\n  text-shadow:0 1px 0 rgba(255,255,255,.65);padding-left:.1em\r\n}\r\n.ipb-set-row{display:flex;align-items:stretch;gap:28px;margin-top:8px;flex:1;min-height:0}\r\n.ipb-set-badge{\r\n  width:86px;height:360px;align-self:center;\r\n  border-radius:50% / 22%;\r\n  background:linear-gradient(180deg,#FF9A4A,#FF6A30 50%,#E85020);\r\n  box-shadow:0 10px 0 #C04018,inset 0 4px 0 rgba(255,255,255,.35),inset 0 -6px 12px rgba(120,30,10,.2);\r\n  display:flex;align-items:center;justify-content:center;color:#fff;\r\n  writing-mode:vertical-rl;text-orientation:mixed;\r\n  font-size:44px;font-weight:900;letter-spacing:.32em;transform:rotate(180deg)\r\n}\r