INSERT INTO skin_screens (id, skin_id, title, html, css, has_video_slot, has_next_video_slot, title_only, default_duration_sec, sort_order, version, created_at, updated_at) VALUES ('f9901137-d73f-438a-96a5-ea81c8cffbb7', 'cc9503c5-6c0d-454f-bfe8-2f88c45f3deb', '수업 대기', '<div class="na-stage">
  <div class="na-scan"></div>
  <div class="na-floor"></div>
  <header class="na-top"><img class="na-logo" src="{{logoUrl}}" alt=""><span class="na-prog">{{program.name}}</span></header>
  <main class="na-center">
    <p class="na-lbl">CLASS</p>
    <h1 class="na-title">{{label}}</h1>
    <p class="na-sub">곧 시작해요</p>
    <p class="na-timer">{{remainingSec}}</p>
    <p class="na-meta">ROUND {{round}} / {{roundTotal}}</p>
  </main>
</div>', '.na-stage{
  --bg:#07051A;
  --bg-image:radial-gradient(ellipse at 50% -10%,#2A0D5C 0%,#07051A 60%);
  --fg:#FFFFFF;--muted:#CFC8FF;--primary:#00F0FF;--secondary:#FF2BD6;--accent:#B6FF3B;--on-accent:#07051A;
  --panel-bg:#120A2E;--panel-border:2px solid #3A2A7A;--panel-radius:16px;
  --pc:{{pointColor}};
  position:relative;width:1920px;height:1080px;overflow:hidden;
  background-color:var(--bg);background-image:var(--bg-image);color:var(--fg);
  font-family:system-ui,sans-serif
}
.na-scan{position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(transparent 0 50%,rgba(255,255,255,.035) 50% 100%);background-size:100% 4px}
.na-floor{position:absolute;left:0;bottom:0;width:100%;height:300px;pointer-events:none;
  background:linear-gradient(0deg,rgba(255,43,214,.18),transparent),repeating-linear-gradient(90deg,rgba(0,240,255,.14) 0 2px,transparent 2px 96px)}
.na-top{position:absolute;left:48px;top:28px;display:flex;align-items:center;gap:20px;z-index:2}
.na-logo{height:48px;width:auto}
.na-prog{font-size:22px;font-weight:700;color:var(--muted);letter-spacing:.08em}
.na-panel{background:var(--panel-bg);border:var(--panel-border);border-radius:var(--panel-radius)}
.na-lbl{font-size:22px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.na-title{font-size:96px;font-weight:800;line-height:1.05;color:var(--fg);text-shadow:0 0 8px #00F0FF,0 0 24px #00F0FF;word-break:keep-all}
.na-sub{font-size:32px;font-weight:600;color:var(--muted);margin-top:12px}
.na-timer{font-size:200px;font-weight:800;color:var(--secondary);text-shadow:0 0 10px #FF2BD6,0 0 28px rgba(255,43,214,.7);font-variant-numeric:tabular-nums;line-height:1}
.na-center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:120px 96px;gap:16px;z-index:1}
.na-step{font-size:28px;color:var(--pc);text-shadow:0 0 14px rgba(182,255,59,.6)}
.na-meta{font-size:26px;color:var(--muted)}
.na-vbox{position:absolute;left:263px;top:288px;width:1394px;height:768px}
.na-video{width:100%;height:100%;background:#0A0722;border-radius:28px}
.na-frame{position:absolute;inset:-14px;border:14px solid #0A0722;border-radius:42px;box-shadow:0 0 28px rgba(0,240,255,.45);pointer-events:none}
.na-frame::after{content:"";position:absolute;inset:0;border:4px solid #00F0FF;border-radius:28px}
.na-hud-top{position:absolute;left:48px;top:28px;right:48px;height:216px;display:grid;grid-template-columns:minmax(300px,340px) minmax(0,1fr) minmax(360px,400px);gap:20px;z-index:2;align-items:stretch}
.na-hud-top .na-panel{min-width:0;overflow:hidden;display:flex;flex-direction:column;justify-content:center}
.na-hud-top .na-step,.na-hud-top .na-panel .na-step{white-space:nowrap;font-size:48px;line-height:1.1}
.na-hud-top .na-name,.na-hud-top .na-title{font-size:52px;text-align:center;margin:0;padding:16px 20px;line-height:1.15;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.na-hud-top .na-timer,.na-hud-top .na-timer-sm{font-size:88px;display:flex;align-items:center;justify-content:center;white-space:nowrap;font-variant-numeric:tabular-nums;line-height:1;padding:0 12px;box-sizing:border-box}
.na-bar{position:absolute;left:48px;top:260px;width:1824px;height:12px;background:#1B1440;border:1px solid #3A2A7A;border-radius:6px;overflow:hidden;z-index:2}
.na-bar i{display:block;height:100%;width:62%;background:linear-gradient(90deg,#00F0FF,#FF2BD6)}
.na-next-v{width:320px;height:180px;background:#1B1440;border:3px solid #FF2BD6;border-radius:12px}
.na-rest-layout{position:absolute;inset:0;display:grid;grid-template-columns:1fr 400px;align-items:center;padding:120px 96px;gap:48px;z-index:1}
.na-chips{display:flex;flex-wrap:wrap;gap:16px;justify-content:center;max-width:1100px;margin-top:24px}
.na-chip{display:flex;align-items:center;gap:14px;min-width:280px;padding:18px 22px;border-radius:999px;background:#1B1440;border:2px solid #3A2A7A;font-size:28px;font-weight:800}
.na-chip em{font-style:normal;width:46px;height:46px;border-radius:999px;display:grid;place-items:center;background:var(--accent);color:var(--on-accent);font-size:24px;font-weight:800}
.na-muscles{margin-top:16px;width:100%;height:120px;border-radius:12px;border:2px dashed #3A2A7A;background:rgba(27,20,64,.6);display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:22px;font-weight:700}
.na-preview-layout{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:80px;gap:32px;z-index:1}
.na-preview-row{display:flex;align-items:flex-start;gap:40px}', 0, 0, 1, NULL, 0, 1, '2026-11-19T04:42:24.391+00:00', '2026-11-19T04:42:24.391+00:00');
