  font-family:var(--display);font-weight:900;letter-spacing:.08em;line-height:.9;
  background:linear-gradient(180deg,#FFC078 0%,#FF8A4A 38%,#E84A3C 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;
