INSERT INTO skin_screens (id, skin_id, title, html, css, has_video_slot, has_next_video_slot, title_only, default_duration_sec, sort_order, version, created_at, updated_at) VALUES ('c24c9049-09e6-47e6-b462-0faf3929e6a7', 'ee64892f-5e69-4b5d-a281-2434c0f9135f', '체인지', '<div class="ipb-stage">
