.ipb-warmup-layout{position:absolute;left:56px;right:56px;top:250px;bottom:56px;z-index:2;display:grid;grid-template-columns:1.55fr .9fr;gap:40px;align-items:stretch}
.ipb-next-col{display:flex;flex-direction:column;align-items:center;gap:0}
.ipb-next-glass{width:100%;padding:28px 28px 32px;display:flex;flex-direction:column;align-items:center;gap:18px;box-sizing:border-box}
