INSERT INTO skin_screens (id, skin_id, title, html, css, has_video_slot, has_next_video_slot, title_only, default_duration_sec, sort_order, version, created_at, updated_at) VALUES ('101dc2c5-776f-48f9-bea0-492d264d773d', 'ee64892f-5e69-4b5d-a281-2434c0f9135f', '체인지 후 미리보기', '<div class="ipb-stage">
  <div class="ipb-decor" aria-hidden="true">
  <div class="ipb-palm-tl"></div>
  <div class="ipb-palm-tr"></div>
  <div class="ipb-palm-bl"></div>
  <div class="ipb-float"></div>
  <div class="ipb-star-lg"></div>
  <div class="ipb-star-sm"></div>
  <div class="ipb-shell"></div>
  <i class="ipb-spark s1"></i><i class="ipb-spark s2"></i><i class="ipb-spark s3"></i><i class="ipb-spark s4"></i>
  <i class="ipb-spark s5"></i><i class="ipb-spark s6"></i>
</div>
  <header class="ipb-hud-top">
    <div class="ipb-glass ipb-hud-glass">
      <div class="ipb-hprog"><i></i><b></b></div>
      <div class="ipb-sec-row">
        <span class="ipb-sec-num">{{remainingSec}}</span>
        <span class="ipb-sec-badge">SEC</span>
      </div>
    </div>
  </header>
  <section class="ipb-split-layout">
    <div class="ipb-panel ipb-video-frame" style="min-height:640px">
      <div data-mvn-next-video class="ipb-video"></div>
    </div>
    <div class="ipb-muscles ipb-glass">
  <img
    class="ipb-muscles-img"
    src="/skins/ipt-power-bell/muscles-front-back.png"
    alt="FRONT / BACK"
    width="710"
    height="700"
  >
</div>
  </section>
  <p class="ipb-hidden-tokens">{{label}} {{next.label}} {{totalSec}} {{pointColor}}</p>
</div>', '.ipb-stage{
  --sand:#FFE8CF;--peach:#FFD2B0;--coral:#FF6A45;--coral-deep:#E84A3C;--aqua:#7ECEC9;--teal:#4DB6AC;--cream:#FFF8F0;--gold:#E8C36A;--ink:#2A3340;--pc:{{pointColor}};
  --display:"Archivo Black","Arial Black",Impact,"Helvetica Neue Black",sans-serif;
  position:relative;width:1920px;height:1080px;overflow:hidden;color:var(--ink);
  font-family:"Trebuchet MS","Segoe UI",Verdana,sans-serif;
  background:
    radial-gradient(ellipse 90% 70% at 75% 85%,rgba(126,206,201,.62) 0%,transparent 58%),
    radial-gradient(ellipse 75% 55% at 18% 12%,rgba(255,210,176,.95) 0%,transparent 52%),
