    radial-gradient(ellipse 140px 48px at 82% 88%,rgba(180,230,225,.5) 0%,transparent 70%),
    radial-gradient(circle at 18% 72%,rgba(255,255,255,.55) 0 2px,transparent 3px),
    radial-gradient(circle at 42% 58%,rgba(255,255,255,.45) 0 1.5px,transparent 3px),
    radial-gradient(circle at 68% 74%,rgba(255,255,255,.4) 0 2px,transparent 3px),
    radial-gradient(circle at 78% 52%,rgba(125,210,205,.4) 0 50px,transparent 90px),
    radial-gradient(circle at 55% 88%,rgba(125,210,205,.3) 0 70px,transparent 120px)
}
.ipb-decor{position:absolute;inset:0;pointer-events:none;z-index:1}
.ipb-decor>div{position:absolute;background-repeat:no-repeat;background-size:contain}
